import React from "react";
import { AbsoluteFill, useCurrentFrame, useVideoConfig } from "remotion";

export const fps = 25;

// ============================================================
// Claude prompt box — typewriter reveal of the prompt text.
// Transparent background. Typing is paced to the VO timings: each
// segment's text is typed within its [start,end] window, and the
// segments concatenate to the exact prompt shown in the screenshot.
// The CSV file chip from the screenshot is intentionally omitted.
// ============================================================
const SEGMENTS: { text: string; start: number; end: number }[] = [
  { text: "Based on these 2 analysis tasks, please prepare four concrete video ideas — each with a working title, format, length, and the data point that supports it.", start: 0, end: 1.5 },
];
const HOLD_SECONDS = 1.5;

const FULL_TEXT = SEGMENTS.map((s) => s.text).join("");
const LAST_END = SEGMENTS.length ? SEGMENTS[SEGMENTS.length - 1].end : 0;
export const durationInFrames = Math.round((LAST_END + HOLD_SECONDS) * fps);

const COLORS = {
  box: "#262624",
  text: "#ECECEC",
  icon: "#8d8d87",
  model: "#cfcfca",
  send: "#C96442",
};

function typedCount(frame: number, segments: typeof SEGMENTS): number {
  let count = 0;
  for (const seg of segments) {
    const startF = seg.start * fps;
    const endF = seg.end * fps;
    if (frame >= endF) {
      count += seg.text.length;
    } else if (frame > startF) {
      const p = (frame - startF) / (endF - startF);
      count += Math.floor(p * seg.text.length);
      break;
    } else {
      break;
    }
  }
  return count;
}

const MicIcon: React.FC<{ size: number }> = ({ size }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke={COLORS.icon} strokeWidth={1.8} strokeLinecap="round" strokeLinejoin="round">
    <rect x="9" y="2.5" width="6" height="11" rx="3" />
    <path d="M5.5 11a6.5 6.5 0 0 0 13 0" />
    <line x1="12" y1="17.5" x2="12" y2="21" />
  </svg>
);

const SendIcon: React.FC<{ size: number }> = ({ size }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="#ffffff" strokeWidth={2.2} strokeLinecap="round" strokeLinejoin="round">
    <line x1="12" y1="19" x2="12" y2="5.5" />
    <path d="M6 11 L12 5 L18 11" />
  </svg>
);

const PromptBox: React.FC = () => {
  const frame = useCurrentFrame();
  const { width } = useVideoConfig();

  const count = typedCount(frame, SEGMENTS);
  const shown = FULL_TEXT.slice(0, count);
  const done = count >= FULL_TEXT.length;
  const caretOn = done ? Math.floor(frame / 15) % 2 === 0 : true;

  const boxW = width * 0.56;
  const pad = width * 0.024;
  const radius = width * 0.018;
  const fontSize = width * 0.0145;
  const textStyle: React.CSSProperties = {
    fontFamily: "Inter, sans-serif",
    fontSize,
    lineHeight: 1.55,
    fontWeight: 400,
    color: COLORS.text,
    whiteSpace: "pre-wrap",
    letterSpacing: "-0.01em",
    margin: 0,
  };

  return (
    <AbsoluteFill style={{ display: "flex", alignItems: "center", justifyContent: "center" }}>
      <div
        style={{
          width: boxW,
          backgroundColor: COLORS.box,
          borderRadius: radius,
          padding: pad,
          display: "flex",
          flexDirection: "column",
          gap: pad * 0.85,
          boxShadow: "0 30px 80px rgba(0,0,0,0.35)",
        }}
      >
        {/* Text area — hidden full text reserves final height; typed text overlays */}
        <div style={{ position: "relative" }}>
          <div style={{ ...textStyle, visibility: "hidden" }}>{FULL_TEXT}</div>
          <div style={{ ...textStyle, position: "absolute", inset: 0 }}>
            {shown}
            <span
              style={{
                display: "inline-block",
                width: fontSize * 0.07,
                height: fontSize * 0.92,
                backgroundColor: COLORS.text,
                marginLeft: fontSize * 0.06,
                transform: `translateY(${fontSize * 0.14}px)`,
                opacity: caretOn ? 1 : 0,
              }}
            />
          </div>
        </div>

        {/* Toolbar */}
        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between" }}>
          <div style={{ color: COLORS.icon, fontSize: fontSize * 1.3, lineHeight: 1, fontFamily: "Inter, sans-serif" }}>+</div>
          <div style={{ display: "flex", alignItems: "center", gap: fontSize * 0.7 }}>
            <span style={{ color: COLORS.model, fontSize: fontSize * 0.82, fontFamily: "Inter, sans-serif" }}>Opus 4.7</span>
            <span style={{ color: COLORS.icon, fontSize: fontSize * 0.82, fontFamily: "Inter, sans-serif" }}>Extra ⌄</span>
            <MicIcon size={fontSize * 1.05} />
            <div
              style={{
                width: fontSize * 1.7,
                height: fontSize * 1.7,
                borderRadius: fontSize * 0.42,
                backgroundColor: COLORS.send,
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                marginLeft: fontSize * 0.1,
              }}
            >
              <SendIcon size={fontSize * 1.0} />
            </div>
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

const MainComposition: React.FC = () => (
  <AbsoluteFill>
    <PromptBox />
  </AbsoluteFill>
);

export default MainComposition;
